function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}
const input = items[0].json.body || items[0].json;
const sessionId = uuid();
const expiresAt = new Date(Date.now() + 1 * 24 * 60 * 60 * 1000);
const baseUrl = input.frontendUrl || items[0].json.frontendUrl || 'http://localhost:5173';
const inviteLink = `${baseUrl}/interview/${sessionId}`;
const candidateEmail = input.candidate_email || input.email;
const candidateName = input.candidate_name || input.name || 'Candidate';
if (!candidateEmail) {
  throw new Error('Missing candidate email. Send email or candidate_email in the webhook body.');
}
return {
  ...input,
  candidate_email: candidateEmail,
  candidate_name: candidateName,
  session_id: sessionId,
  invite_link: inviteLink,
  token_hash: sessionId,
  expires_at: expiresAt.toISOString(),
  status: 'invited'
};

const input = $node["Generate Session"].json;
const sessionId = $node["Store Session"].json.id || input.session_id;
const reviewedQuestions = Array.isArray(input.questions) ? input.questions : [];

function normalizeQuestionType(type) {
  const t = String(type || '').toLowerCase().trim();
  if (t === 'behavioral') return 'behavioral';
  if (t === 'situational' || t === 'gap_probe') return 'situational';
  if (t === 'cultural') return 'cultural';
  return 'technical';
}

const intro = {
  session_id: sessionId,
  question_text: "Hello! I am your AI Interviewer today. Welcome to your interview. To start off, how are you doing today?",
  question_type: "cultural",
  order_index: 0,
  source: "hr_reviewed_intro"
};

const questions = reviewedQuestions
  .filter(q => q && String(q.question_text || '').trim())
  .map((q, index) => ({
    session_id: sessionId,
    question_text: String(q.question_text).trim(),
    question_type: normalizeQuestionType(q.question_type),
    order_index: index + 1,
    source: q.source || 'hr_reviewed_llm'
  }));

return [intro, ...questions].map(question => ({ json: question }));

const storeSession = $("Store Session").first().json;
const genSession = $("Generate Session").first().json;
return items.map(item => ({
  json: {
    actor_type: 'system',
    action: 'interview_invite_sent',
    resource_type: 'interview_sessions',
    resource_id: storeSession.id,
    details: { email: genSession.candidate_email }
  }
}));

const jd = $input.first().json;
const role = jd.parsed_roles?.[0] || 'the position';
return [{ json: { position: role } }];

const genSession = $("Generate Session").first().json;
const storeSession = $("Store Session").first().json;
const position = $("Extract Position1").first().json.position || 'the position';
return [{
  json: {
    candidate_email: genSession.candidate_email,
    candidate_name: genSession.candidate_name,
    invite_link: genSession.invite_link,
    expires_at: genSession.expires_at,
    session_id: storeSession.id,
    position: position
  }
}];

const sessionId = $("Store Session").first().json.id;
const content = JSON.parse($input.first().json.choices[0].message.content);
return [{
  json: {
    session_id: sessionId,
    version: 'v1',
    competencies: content.competencies || [],
    question_plan: content.question_plan || [],
    candidate_summary: content.candidate_summary || { strengths: [], gaps: [], claims_to_validate: [] },
    constraints: content.constraints || { max_primary_questions: 10, max_follow_ups_per_question: 1 }
  }
}];
